typedef unsigned int u_int;

template <int count>
struct SplineCoeffs {
    float a[count];
    float b[count];
    float c[count];
    float d[count];
};

struct WaveProfileCoeffs {
    SplineCoeffs<16> y;
    SplineCoeffs<16> z;
};

struct WavePositionHint {
    float x;
    float z;
    float xprofile;
    u_int xcell;
    u_int zcell;
    u_int xgrid;
    u_int zgrid;
    WaveProfileCoeffs wpc;
};

struct WaveControlPointData {
    char pad[0x2400];
    u_int numcontrol;
    u_int numprofile;
};

extern WaveControlPointData *WAVE_ControlPoints;
extern float WAVE_ControlZ[];
extern float WAVE_BaseProfile[];
extern float WAVE_MeshGridX[];
extern float WAVE_ControlGridZ[];
extern u_int WAVE_MeshStepX;
extern u_int WAVE_MeshStepZ;

__asm__(".equ WAVE_ControlPoints, 0x004846F0");
__asm__(".equ WAVE_ControlZ, 0x00585A40");
__asm__(".equ WAVE_BaseProfile, 0x00585940");
__asm__(".equ WAVE_MeshGridX, 0x00485180");
__asm__(".equ WAVE_ControlGridZ, 0x0048AE90");
__asm__(".equ WAVE_MeshStepX, 0x00484630");
__asm__(".equ WAVE_MeshStepZ, 0x00484634");

inline u_int SPLINE_BinarySearch(const float *x, u_int n, const float &valx)
{
    u_int lo = 0, hi = n - 1, mid;
    while (hi - lo > 1)
    {
        mid = (lo + hi) / 2;
        if (x[mid] < valx) lo = mid;
        else hi = mid;
    }

    return lo;
}

static void WAVE_BuildHint(WavePositionHint *hint, float x0, float profilex0, float z0,
    const WaveProfileCoeffs &wpc)
{
    hint->x = x0;
    hint->z = z0;
    hint->xprofile = profilex0;
    hint->zcell = SPLINE_BinarySearch(WAVE_ControlZ, WAVE_ControlPoints->numcontrol, z0);
    // This is only needed for WAVE_FindRegion for now
    hint->xcell = SPLINE_BinarySearch(WAVE_BaseProfile, WAVE_ControlPoints->numprofile, profilex0);
    // These are only needed for WAVE_TrackFloater for now
    hint->xgrid = SPLINE_BinarySearch(WAVE_MeshGridX, WAVE_MeshStepX + 1, x0);
    hint->zgrid = SPLINE_BinarySearch(WAVE_ControlGridZ, WAVE_MeshStepZ + 1, z0);
    if (&hint->wpc != &wpc)
    {
        hint->wpc = wpc;
    }
}
